package com.marketplace;
import java.util.*;import java.math.*;import java.nio.file.*;import java.io.*;import javax.imageio.ImageIO;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.beans.factory.annotation.Value;
@RestController @RequestMapping("/api/seller") public class Seller {
 final Db d;final Access a;final Commerce c;final Path uploads;Seller(Db d,Access a,Commerce c,@Value("${app.uploads}")String path){this.d=d;this.a=a;this.c=c;uploads=Path.of(path).toAbsolutePath().normalize();}
 @GetMapping("/overview") Object overview(HttpSession s,@RequestParam(defaultValue="30")int days){long sid=a.store(s);if(days<1||days>365)throw new IllegalArgumentException();var m=d.one("select coalesce(sum(i.unit_price*i.quantity-i.discount),0) revenue,count(distinct i.order_id) orders from order_items i join orders o on o.id=i.order_id join seller_orders so on so.id=i.seller_order_id where so.seller_id=? and o.payment_state='PAID' and so.fulfillment not in ('CANCELLED','RETURNED') and o.created_at>=now()-make_interval(days=>?)",sid,days);m.put("products",d.id("select count(*) from products where seller_id=? and active",sid));m.put("low_stock",d.id("select count(*) from variants v join products p on p.id=v.product_id where p.seller_id=? and v.stock-v.reserved<=v.threshold",sid));m.put("trend",d.all("select to_char(bucket,'Mon DD') label,coalesce(sum(sales.revenue),0) revenue from generate_series(current_date-(?-1),current_date,interval '1 day') as series(bucket) left join (select o.created_at::date date,sum(i.unit_price*i.quantity-i.discount) revenue from order_items i join orders o on o.id=i.order_id join seller_orders so on so.id=i.seller_order_id where so.seller_id=? and o.payment_state='PAID' and so.fulfillment not in ('CANCELLED','RETURNED') group by o.created_at::date)sales on sales.date=bucket::date group by bucket order by bucket",days,sid));m.put("best",d.all("select i.title,sum(i.quantity) units,sum(i.unit_price*i.quantity-i.discount) revenue from order_items i join seller_orders so on so.id=i.seller_order_id join orders o on o.id=i.order_id where so.seller_id=? and o.payment_state='PAID' and so.fulfillment not in ('RETURNED','CANCELLED') and o.created_at>=now()-make_interval(days=>?) group by i.title order by revenue desc limit 5",sid,days));return m;}
 @GetMapping("/products") Object products(HttpSession s){return d.all(Catalog.SELECT+" where p.seller_id=? order by p.id desc",a.store(s));}
 record Product(String title,String brand,String description,long categoryId,String image,BigDecimal price,BigDecimal originalPrice,int stock,String color,Integer version,boolean active){}
 void validate(Product p){Catalog.check(p.title(),3,180);Catalog.check(p.brand(),1,100);Catalog.check(p.description(),10,4000);Catalog.check(p.color(),1,40);if(p.price()==null||p.price().signum()<=0||p.price().scale()>2||p.price().compareTo(new BigDecimal("999999"))>0||p.originalPrice()==null||p.originalPrice().signum()<0||p.stock()<0||p.stock()>100000)throw new IllegalArgumentException();if(p.image()==null||!p.image().matches("/(assets/[a-zA-Z0-9-]+\\.(svg|jpg)|uploads/[a-f0-9-]+\\.png)"))throw new IllegalArgumentException();d.one("select id from categories where id=?",p.categoryId());}
 @PostMapping("/products") @Transactional Object create(HttpSession s,@RequestBody Product p){validate(p);long sid=a.store(s);long id=d.id("insert into products(seller_id,category_id,title,brand,description,image) values(?,?,?,?,?,?) returning id",sid,p.categoryId(),p.title(),p.brand(),p.description(),p.image());d.exec("insert into variants(product_id,sku,color,price,original_price,stock) values(?,?,?,?,?,?)",id,"MP-"+UUID.randomUUID(),p.color(),p.price(),p.originalPrice(),p.stock());audit(s,"PRODUCT_CREATED","product:"+id,p.title());return Map.of("id",id);}
 @PutMapping("/products/{id}") @Transactional Object edit(HttpSession s,@PathVariable long id,@RequestBody Product p){validate(p);long sid=a.store(s);if(d.exec("update products set category_id=?,title=?,brand=?,description=?,image=?,active=?,version=version+1 where id=? and seller_id=? and version=?",p.categoryId(),p.title(),p.brand(),p.description(),p.image(),p.active(),id,sid,p.version())!=1)throw new Failure(409,"EDIT_CONFLICT","Listing changed or is not owned by you; reload");audit(s,"PRODUCT_UPDATED","product:"+id,p.title());return Map.of("ok",true);}
 record Variant(String color,BigDecimal price,BigDecimal originalPrice,int stock){}
 @PostMapping("/products/{id}/variants") @Transactional Object variant(HttpSession s,@PathVariable long id,@RequestBody Variant v){d.one("select id from products where id=? and seller_id=?",id,a.store(s));Catalog.check(v.color(),1,40);if(v.price()==null||v.price().signum()<=0||v.price().scale()>2||v.originalPrice()==null||v.originalPrice().signum()<0||v.stock()<0)throw new IllegalArgumentException();long vid=d.id("insert into variants(product_id,sku,color,price,original_price,stock) values(?,?,?,?,?,?) returning id",id,"MP-"+UUID.randomUUID(),v.color(),v.price(),v.originalPrice(),v.stock());audit(s,"VARIANT_CREATED","variant:"+vid,v.color());return Map.of("id",vid);}
 @PutMapping("/variants/{id}") @Transactional Object editVariant(HttpSession s,@PathVariable long id,@RequestBody Variant v){d.one("select v.id from variants v join products p on p.id=v.product_id where v.id=? and p.seller_id=? for update of v",id,a.store(s));Catalog.check(v.color(),1,40);if(v.price()==null||v.price().signum()<=0||v.price().scale()>2||v.originalPrice()==null||v.originalPrice().signum()<0)throw new IllegalArgumentException();d.exec("update variants set color=?,price=?,original_price=? where id=?",v.color(),v.price(),v.originalPrice(),id);audit(s,"VARIANT_UPDATED","variant:"+id,v.color());return Map.of("ok",true);}
 @GetMapping("/inventory") Object inventory(HttpSession s){return d.all("select v.*,p.title,p.image from variants v join products p on p.id=v.product_id where p.seller_id=? order by p.id,v.id",a.store(s));}
 record Adjustment(int delta,String reason){}
 @PostMapping("/inventory/{id}") @Transactional Object stock(HttpSession s,@PathVariable long id,@RequestBody Adjustment b){Catalog.check(b.reason(),5,200);if(b.delta()==0||Math.abs((long)b.delta())>100000)throw new IllegalArgumentException();long sid=a.store(s);d.one("select v.id from variants v join products p on p.id=v.product_id where v.id=? and p.seller_id=? for update of v",id,sid);if(d.exec("update variants set stock=stock+? where id=? and stock+?>=reserved",b.delta(),id,b.delta())!=1)throw new Failure(409,"RESERVED_STOCK","Cannot remove reserved inventory");d.exec("insert into inventory_ledger(variant_id,delta,reason) values(?,?,?)",id,b.delta(),b.reason());if(d.id("select count(*) from variants where id=? and stock-reserved<=threshold",id)>0)c.notify(a.uid(s),"Low stock after adjustment for variant #"+id);audit(s,"STOCK_ADJUSTMENT","variant:"+id,b.reason());return Map.of("ok",true);}
 @GetMapping("/inventory/{id}/history") Object history(HttpSession s,@PathVariable long id){d.one("select v.id from variants v join products p on p.id=v.product_id where v.id=? and p.seller_id=?",id,a.store(s));return d.all("select * from inventory_ledger where variant_id=? order by id desc limit 100",id);}
 @GetMapping("/orders") Object orders(HttpSession s,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String status){Catalog.check(q,0,100);return d.all("select so.*,o.payment_state,o.created_at,u.name customer,coalesce(sum(i.unit_price*i.quantity-i.discount+i.tax+i.shipping),0) total,string_agg(i.title,', ') items from seller_orders so join orders o on o.id=so.order_id join users u on u.id=o.user_id join order_items i on i.seller_order_id=so.id where so.seller_id=? and (?='' or so.fulfillment=?) and (?='' or o.id::text=? or u.name ilike ?) group by so.id,o.id,u.id order by so.id desc",a.store(s),status,status,q,q,"%"+q+"%");}
 record Fulfill(String status,String tracking){}
 @PostMapping("/orders/{id}/fulfillment") @Transactional Object fulfill(HttpSession s,@PathVariable long id,@RequestBody Fulfill f){long sid=a.store(s);var pre=d.one("select order_id from seller_orders where id=? and seller_id=?",id,sid);var o=d.one("select * from orders where id=? for update",pre.get("order_id"));var so=d.one("select * from seller_orders where id=? and seller_id=? for update",id,sid);String from=Db.str(so,"fulfillment");if(!o.get("payment_state").equals("PAID")||!((from.equals("PROCESSING")&&f.status().equals("SHIPPED"))||(from.equals("SHIPPED")&&f.status().equals("DELIVERED"))))throw new Failure(409,"INVALID_TRANSITION","Allowed transitions: paid processing → shipped → delivered");String tracking=f.tracking()==null?"SIM-"+id:f.tracking();Catalog.check(tracking,1,100);d.exec("update seller_orders set fulfillment=?,tracking=? where id=?",f.status(),tracking,id);c.notify(Db.n(o,"user_id"),"Seller order #"+id+" "+f.status().toLowerCase()+" (simulated shipment)");audit(s,"FULFILLMENT","seller-order:"+id,f.status());return Map.of("ok",true);}
 @GetMapping("/returns") Object returns(HttpSession s){return d.all("select r.*,so.seller_id from returns r join seller_orders so on so.id=r.seller_order_id where so.seller_id=? order by r.id desc",a.store(s));}
 @PostMapping("/returns/{id}/approve") @Transactional Object approve(HttpSession s,@PathVariable long id){long sid=a.store(s);var r=d.one("select r.* from returns r join seller_orders so on so.id=r.seller_order_id where r.id=? and so.seller_id=?",id,sid);d.one("select id from orders where id=? for update",r.get("order_id"));r=d.one("select * from returns where id=? for update",id);if(r.get("state").equals("REFUNDED"))return r;c.refund(Db.n(r,"seller_order_id"),true);d.exec("update returns set state='REFUNDED' where id=?",id);audit(s,"RETURN_REFUNDED","return:"+id,"Demo refund and restock");return Map.of("ok",true);}
 @GetMapping(value="/export",produces="text/csv") String csv(HttpSession s){long sid=a.store(s);StringBuilder b=new StringBuilder("Order,Product,Quantity,Unit price\r\n");for(var row:d.all("select i.* from order_items i join seller_orders so on so.id=i.seller_order_id where so.seller_id=? order by i.id",sid))b.append(row.get("order_id")).append(',').append(csvCell(Db.str(row,"title"))).append(',').append(row.get("quantity")).append(',').append(row.get("unit_price")).append("\r\n");return b.toString();}
 static String csvCell(String s){if(s.matches("^[\\s]*[=+@-].*"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 @GetMapping("/settings") Object settings(HttpSession s){return d.one("select id,name,active from stores where id=?",a.store(s));}
 @PostMapping("/settings") Object settings(HttpSession s,@RequestBody Map<String,String>b){Catalog.check(b.get("name"),3,100);d.exec("update stores set name=? where id=?",b.get("name"),a.store(s));return Map.of("ok",true);}
 @PostMapping("/uploads") Object upload(HttpSession s,@RequestParam MultipartFile file)throws IOException{a.store(s);if(file.getSize()>5*1024*1024)throw new IllegalArgumentException();byte[] data=file.getBytes();if(data.length<8||!((data[0]==(byte)0x89&&data[1]==0x50)||(data[0]==(byte)0xff&&data[1]==(byte)0xd8)))throw new Failure(400,"INVALID_IMAGE","PNG and JPEG images only");try(var stream=ImageIO.createImageInputStream(new ByteArrayInputStream(data))){var readers=ImageIO.getImageReaders(stream);if(!readers.hasNext())throw new IllegalArgumentException();var reader=readers.next();reader.setInput(stream);if((long)reader.getWidth(0)*reader.getHeight(0)>16000000)throw new Failure(400,"IMAGE_TOO_LARGE","Maximum 16 megapixels");reader.dispose();}var image=ImageIO.read(new ByteArrayInputStream(data));if(image==null)throw new IllegalArgumentException();Files.createDirectories(uploads);String name=UUID.randomUUID()+".png";ImageIO.write(image,"png",uploads.resolve(name).toFile());return Map.of("url","/uploads/"+name);}
 void audit(HttpSession s,String action,String resource,String summary){d.exec("insert into audit_logs(actor,action,resource,summary) values(?,?,?,?)",a.uid(s),action,resource,summary);}
}
